'use strict';
const $=id=>document.getElementById(id), levels=['空いている','やや混雑','満席','不明'], colors=['#278963','#bf790c','#cd5056','#7c8582'], categories=['カフェ','図書館','自習室','コワーキング'], symbols=['☕','本','✎','▣'];
const key='workspot-web-v1';let storageOK=true;
function read(k,fallback){try{return JSON.parse(localStorage.getItem(k))??fallback}catch{storageOK=false;return fallback}}
let profiles=read(key+'-profiles',{}),visits=read(key+'-visits',[]);if(!profiles||typeof profiles!=='object'||Array.isArray(profiles))profiles={};if(!Array.isArray(visits))visits=[];
const spots=Array.from({length:50},(_,i)=>({id:String(i+1),name:i===0?'PR・サンプルカフェ':`サンプル・${categories[i%4]}${String(i+1).padStart(2,'0')}`,category:categories[i%4],lat:35.695+(((i*17+13)%101)/100-.5)*.054,lon:139.705+(((i*43+27)%103)/102-.5)*.054,level:i===0?0:(i*7+1)%4,sponsored:i===0}));
function data(s){const p=profiles[s.id]||{};return {...s,name:typeof p.name==='string'&&p.name.trim()?p.name:s.name,menu:typeof p.menu==='string'?p.menu:'',hours:typeof p.hours==='string'?p.hours:'',memo:typeof p.memo==='string'?p.memo:'',level:Number.isInteger(p.level)&&p.level>=0&&p.level<4?p.level:s.level}}
function persist(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{toast('保存できません。ブラウザの保存設定を確認してください。');return false}}
function toast(t){$('toast').textContent=t;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,4500)}
let map,layer,userMarker,position=null,watch=null,enabled=false,lastFix=0;const markers=new Map();
if(window.L){map=L.map('map',{zoomControl:true}).setView([35.695,139.705],14);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map).on('tileerror',()=>{$('location-status').textContent='地図画像を読み込めません。接続を確認してください。'});layer=L.layerGroup().addTo(map)}else{$('map').textContent='地図を読み込めません。ページを再読み込みしてください。'}
function filtered(){return spots.map(data).filter(s=>(!$('category').value||s.category===$('category').value)&&(!$('only-available').checked||s.level===0))}
function renderMap(){$('result-count').textContent=filtered().length+' サンプル';if(!map)return;layer.clearLayers();markers.clear();for(const s of filtered()){const node=document.createElement('div');node.className='pin'+(s.sponsored?' sponsor':'');node.style.background=colors[s.level];node.textContent=s.sponsored?`☕ PR · ${s.name}`:symbols[categories.indexOf(s.category)];const marker=L.marker([s.lat,s.lon],{icon:L.divIcon({html:node,className:'',iconSize:s.sponsored?[145,56]:[33,33],iconAnchor:s.sponsored?[72,56]:[16,33]}),title:`${s.name}・${levels[s.level]}`,alt:`${s.name}・${levels[s.level]}`,zIndexOffset:s.sponsored?1000:0}).on('click',()=>detail(s.id)).addTo(layer);markers.set(s.id,marker)}}
function detail(id){const s=data(spots.find(s=>s.id===id));$('detail-name').textContent=s.name;const root=$('detail-body');root.replaceChildren();for(const [title,value] of [['混雑状況',levels[s.level]],['種類',s.category],['メニュー',s.menu||'未設定'],['営業時間',s.hours||'未設定'],['お知らせ',s.memo||'未設定']]){const h=document.createElement('h2'),p=document.createElement('p');h.textContent=title;p.textContent=value;root.append(h,p)}$('detail').showModal()}
function tab(name){document.querySelectorAll('.page').forEach(e=>e.hidden=e.id!==name);document.querySelectorAll('[data-tab]').forEach(b=>{if(b.dataset.tab===name)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(name==='explore')map?.invalidateSize();if(name==='facility')loadProfile();if(name==='history')renderVisits();window.scrollTo(0,0)}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());$('search-open').onclick=()=>$('search-dialog').showModal();$('category').onchange=renderMap;$('only-available').onchange=renderMap;
let lastSearch=0;const searchCache=new Map();$('search-form').onsubmit=async e=>{e.preventDefault();const q=$('query').value.trim();renderMap();if($('nearby-list').childElementCount&&position)nearby();if(!q){$('search-results').replaceChildren();$('search-status').textContent='';$('search-dialog').close();toast(filtered().length?filtered().length+'件の施設を表示しました。':'条件に合うサンプル施設はありません。');return}if(Date.now()-lastSearch<1500)return;lastSearch=Date.now();$('search-submit').disabled=true;$('search-results').replaceChildren();$('search-status').textContent='検索中…';try{let results=searchCache.get(q);if(!results){const response=await fetch('https://photon.komoot.io/api/?'+new URLSearchParams({q,limit:'5'}),{signal:AbortSignal.timeout(12000)});if(!response.ok)throw Error('search');results=(await response.json()).features;searchCache.set(q,results)}$('search-status').textContent=results.length?'場所を選んでください。':'見つかりませんでした。駅名や地名を変えてください。';for(const result of results){const b=document.createElement('button');b.className='result';b.textContent=result.properties.name||q;const sub=document.createElement('small');sub.textContent=[result.properties.city,result.properties.state,result.properties.country].filter(Boolean).join(' / ');b.append(sub);b.onclick=()=>{const [lon,lat]=result.geometry.coordinates;map?.setView([lat,lon],14);$('area').textContent=result.properties.name||q;$('search-dialog').close();$('location-status').textContent='';};$('search-results').append(b)}}catch{$('search-status').textContent='検索サービスに接続できません。しばらくして再試行してください。'}finally{$('search-submit').disabled=false}};
function distance(a,b){const rad=Math.PI/180,dlat=(b.lat-a.lat)*rad,dlon=(b.lon-a.lon)*rad;const h=Math.sin(dlat/2)**2+Math.cos(a.lat*rad)*Math.cos(b.lat*rad)*Math.sin(dlon/2)**2;return 6371000*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h))}
function nearby(){if(!position){toast('「現在地から探す」を押してください。');return}const root=$('nearby-list');root.replaceChildren();const h=document.createElement('h2');h.textContent='3km以内のサンプル施設';root.append(h);const list=filtered().map(s=>({...s,dist:distance(position,s)})).filter(s=>s.dist<=3000).sort((a,b)=>a.dist-b.dist);if(!list.length){const p=document.createElement('p');p.textContent='この周辺にサンプル施設はありません。';root.append(p)}for(const s of list){const b=document.createElement('button');b.className='result';b.textContent=`${s.name} · 約${Math.round(s.dist)}m`;b.onclick=()=>detail(s.id);root.append(b)}}
function locationError(){$('locate').disabled=false;interrupt('位置情報の取得エラー');$('location-status').textContent='位置情報を取得できません。許可しなくても駅名検索は使えます。';$('detect-status').textContent=enabled?'位置情報を取得できません。検知を停止して再試行してください。':'検知はオフです'}
$('locate').onclick=()=>{if(!navigator.geolocation){locationError();return}$('locate').disabled=true;$('location-status').textContent='取得中…';navigator.geolocation.getCurrentPosition(p=>{$('locate').disabled=false;position={lat:p.coords.latitude,lon:p.coords.longitude};if(map){map.setView([position.lat,position.lon],15);if(userMarker)map.removeLayer(userMarker);userMarker=L.circleMarker([position.lat,position.lon],{radius:8,color:'white',fillColor:'#3478f6',fillOpacity:1,weight:3}).addTo(map)}$('area').textContent='現在地周辺';$('location-status').textContent='';nearby()},locationError,{enableHighAccuracy:true,timeout:15000,maximumAge:0})};
function populateFacilities(){const selected=$('facility-select').value;$('facility-select').replaceChildren();for(const s of spots.map(data)){const o=document.createElement('option');o.value=s.id;o.textContent=s.name;$('facility-select').append(o)}if(selected)$('facility-select').value=selected}
function selected(){return data(spots.find(s=>s.id===$('facility-select').value)||spots[0])}
function loadProfile(){const s=selected();for(const k of ['name','menu','hours','memo'])$(k).value=s[k];$('save-status').textContent='';renderCrowd()}
function renderCrowd(){const s=selected();$('crowd-buttons').replaceChildren();levels.slice(0,3).forEach((label,i)=>{const b=document.createElement('button');b.textContent=(s.level===i?'✓　':'○　')+label;b.style.background=colors[i]+'16';b.style.color=colors[i];b.setAttribute('aria-pressed',s.level===i);b.onclick=()=>updateLevel(i);$('crowd-buttons').append(b)})}
function updateLevel(level){const s=selected(),next={...profiles,[s.id]:{...profiles[s.id],level}};if(persist(key+'-profiles',next)){profiles=next;renderCrowd();renderMap();toast('保存しました')}}$('unknown').onclick=()=>updateLevel(3);$('facility-select').onchange=loadProfile;
$('profile-form').onsubmit=e=>{e.preventDefault();const s=selected(),name=$('name').value.trim();if(!name){$('name').focus();return}const next={...profiles,[s.id]:{...profiles[s.id],name,menu:$('menu').value,hours:$('hours').value,memo:$('memo').value}};if(persist(key+'-profiles',next)){profiles=next;populateFacilities();renderMap();$('save-status').textContent='保存しました。'}};
function interrupt(reason){let changed=false;visits.forEach(v=>{if(v.end==null){v.end=v.last;v.reason=reason;changed=true}});if(changed)persist(key+'-visits',visits);renderVisits()}
function renderVisits(){const root=$('visits');root.replaceChildren();if(!visits.length){root.textContent='履歴はありません';return}for(const v of [...visits].reverse()){const card=document.createElement('article');card.className='card visit';const h=document.createElement('h3');h.textContent=v.name;card.append(h);for(const t of [`開始：${new Date(v.start).toLocaleString('ja-JP')}`,`終了：${v.end?new Date(v.end).toLocaleString('ja-JP'):'未確定'}`,`推定滞在時間：${Math.max(0,Math.floor(((v.end??v.last)-v.start)/1000))}秒`,v.reason||'周辺で観測中（最終観測までの時間）']){const p=document.createElement('p');p.textContent=t;card.append(p)}root.append(card)}}
function stop(reason){if(watch!==null)navigator.geolocation.clearWatch(watch);watch=null;interrupt(reason)}
function start(){if(!enabled||document.hidden)return;if(!navigator.geolocation){locationError();return}watch=navigator.geolocation.watchPosition(p=>{if(!enabled||document.hidden)return;const now=p.timestamp;if(Date.now()-now>15000||now<=lastFix)return;if(p.coords.accuracy>50){interrupt('位置精度不足による中断');$('detect-status').textContent='位置精度が不足しています。検知は保留中です。';return}if(lastFix&&now-lastFix>60000)interrupt('位置更新の途絶による中断');lastFix=now;const current={lat:p.coords.latitude,lon:p.coords.longitude};for(const s of spots.map(data)){const d=distance(current,s),v=visits.find(v=>v.spotID===s.id&&v.end==null);if(v){v.last=now;if(d-p.coords.accuracy>150){v.end=now;v.reason='周辺退出を検知'}}else if(d+p.coords.accuracy<=100){visits.push({spotID:s.id,name:s.name,start:now,last:now,end:null})}}if(!persist(key+'-visits',visits)){enabled=false;$('consent').checked=false;stop('保存エラーによる中断')}$('detect-status').textContent=enabled?'施設周辺を検知中（屋内入店は確認できません）':'保存エラーで停止しました';renderVisits()},locationError,{enableHighAccuracy:true,maximumAge:0,timeout:15000})}
$('consent').onchange=()=>{if($('consent').checked){$('consent').checked=false;$('consent-dialog').showModal()}else{enabled=false;stop('同意撤回による中断');$('detect-status').textContent='検知はオフです'}};$('accept-consent').onclick=()=>{enabled=true;lastFix=0;$('consent').checked=true;$('consent-dialog').close();$('detect-status').textContent='位置情報の許可・取得を待っています…';start()};
$('clear-history').onclick=()=>{if(!confirm('検知を停止し、このブラウザの訪問履歴をすべて削除しますか？'))return;enabled=false;$('consent').checked=false;stop('削除');try{localStorage.removeItem(key+'-visits');visits=[];renderVisits();$('detect-status').textContent='検知はオフです'}catch{toast('削除できませんでした。')}};
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop('画面非表示による中断');else if(enabled){lastFix=0;start()}});window.addEventListener('pagehide',()=>stop('ページ終了による中断'));interrupt('ページ終了による中断');populateFacilities();loadProfile();renderMap();
new ResizeObserver(()=>{document.documentElement.style.setProperty('--dock',$('dock').getBoundingClientRect().height+'px');map?.invalidateSize()}).observe($('dock'));if(!storageOK)toast('保存データを読み込めませんでした。ブラウザの設定を確認してください。');
